export const root: number = 0;

/** The window this artifact is, as `<Window>` declared it. */
export const windowConfig = {
  title: "dziri — compiled UI",
  width: 1040,
  height: 700,
  minWidth: 520,
  minHeight: 400,
} satisfies WindowConfig;

/**
 * Each route's own top-level nodes, in the window's match order.
 *
 * Navigation writes `hidden` over the routes leaving the chain and clears it over
 * the ones joining — bounded by route count, not by node count.
 */
export const routeNodes = [
  { path: "/", roots: [22], parent: -1 },
  { path: "animations", roots: [56], parent: -1 },
  { path: "borders", roots: [147], parent: -1 },
  { path: "colors", roots: [199], parent: -1 },
  { path: "controls", roots: [253], parent: -1 },
  { path: "features", roots: [477], parent: -1 },
  { path: "layout", roots: [605], parent: -1 },
  { path: "products", roots: [656], parent: -1 },
  { path: "reactivity", roots: [675], parent: -1 },
  { path: "spacing", roots: [880], parent: -1 },
  { path: "transforms", roots: [936], parent: -1 },
  { path: "typography", roots: [1009], parent: -1 },
  { path: "products/new", roots: [665], parent: 7 },
  { path: "products/$id", roots: [670], parent: 7 },
] satisfies RouteNodes[];

/** Index in `routeNodes` of the route the emitted `hidden` column shows. */
export const initialRoute: number = 0;

/**
 * The window's route, if it declared one — `<Window route={…}>`.
 *
 * Navigation's entire runtime: the host subscribes, resolves the path against
 * `routeNodes`, and writes `hidden`. Null when the window never navigates.
 */
export const routeSignal: ReadonlySignal<string> | null = route;

/** Folder name of the window, for diagnostics and multi-window dispatch later. */
export const windowId: string = "main";
